//
// Signal's WebSocket framing (WebSocketMessage protobufs, generated by
// protopiler like upstream) on top of the Tor transport.

import { signalservice } from './protos.mjs';
import { openSignalSocket, withDeadline } from '../transport/index.js';

export const CHAT_URL = 'wss://chat.signal.org/v1/websocket/';
export const PROVISIONING_URL = 'wss://chat.signal.org/v1/websocket/provisioning/';

const { WebSocketMessage, ProvisioningAddress } = signalservice;

export const encodeMessage = message => WebSocketMessage.encode(message);
export const decodeMessage = bytes => WebSocketMessage.decode(bytes);

let nextRequestId = 1n;

/** Sends one request on an open chat socket and resolves to its response. */
export async function request(socket, verb, path, { timeoutMs = 30_000, body, headers } = {}) {
  const id = nextRequestId++;
  await socket.send(
    encodeMessage({ type: WebSocketMessage.Type.REQUEST, request: { verb, path, id, body, headers } })
  );
  return withDeadline(
    (async () => {
      for (;;) {
        const bytes = await socket.recv();
        if (bytes === null) throw new Error('socket closed by server');
        const message = decodeMessage(bytes);
        if (message.type === WebSocketMessage.Type.RESPONSE && message.response?.id === id) {
          return message.response;
        }
      }
    })(),
    timeoutMs,
    `no response to ${verb} ${path} within ${timeoutMs / 1000}s`
  );
}

/**
 * Opens the provisioning socket (the first step of linking a device) and
 * waits for the server to push this session's provisioning address, which
 * is what a link QR code carries. Acknowledges it and resolves to
 * {socket, address, verb, path}. The caller owns the socket.
 */
export async function receiveProvisioningAddress(client, { timeoutMs = 60_000 } = {}) {
  const socket = await withDeadline(
    openSignalSocket(client, PROVISIONING_URL),
    timeoutMs,
    `provisioning socket not open after ${timeoutMs / 1000}s`
  );
  try {
    const bytes = await withDeadline(
      socket.recv(),
      timeoutMs,
      `no provisioning address within ${timeoutMs / 1000}s`
    );
    if (bytes === null) throw new Error('provisioning socket closed by server');
    const message = decodeMessage(bytes);
    if (message.type !== WebSocketMessage.Type.REQUEST || !message.request) {
      throw new Error(`expected a request from the server, got message type ${message.type}`);
    }
    const { verb, path, body, id } = message.request;
    const address = body ? ProvisioningAddress.decode(body).address : null;
    if (!address) throw new Error(`server request ${verb} ${path} carried no provisioning address`);
    await socket.send(
      encodeMessage({
        type: WebSocketMessage.Type.RESPONSE,
        response: { id, status: 200, message: 'OK' },
      })
    );
    return { socket, address, verb, path };
  } catch (error) {
    await socket.close().catch(() => {});
    throw error;
  }
}
